Given an array arr[] of n integers, construct a product array res[] (of the same size) such that res[i] is equal to the product of all the elements of arr[] except arr[i]. Example: Input: arr[] = [10, 3, 5, 6, 2]Output: [180, 600, 360, 300, 900]Explanation: For i=0, res[i] = 3 * 5 * 6 * 2 is 180.For i = 1, res[i] = 10 * 5 * 6 * 2 is 600.For i = 2, res[i] = 10 * 3 * 6 * 2 is 360.For i = 3, res[i] = 10 * 3 * 5 * 2 is 300.For i = 4, res[i] = 10 * 3 * 5 * 6 is 900.Input: arr[] = [12, 0]Output: [0, 12]Explanation: For i = 0, res[i] = 0.For i = 1, res[i] = 12.Try It YourselfTable of Content[Naive Approach] Using Nested Loops - O(n^2) Time and O(1) Space[Better approach] Using Prefix and Suffix Array - O(n) Time and O(n) Space[Efficient Approach] Using Product Array - O(n) Time and O(1) Space[Naive Approach] Using Nested Loops - O(n^2) Time and O(n) SpaceThe idea is to compute the product of all elements except the current one by fixing the index and multiplying all other elements in the array. Doing this for every position generates the required result array.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> productExceptSelf(vector<int>& arr) {
    int n = arr.size();

    // Fill result array with 1
    vector<int> res(n, 1);

    for (int i = 0; i < n; i++) {

        // Compute product of all elements except arr[i]
        for (int j = 0; j < n; j++) {
            if (i != j) 
                res[i] *= arr[j];
        }
    }

    return res;
}

int main() {
    vector<int> arr = {10, 3, 5, 6, 2};
    vector<int> res = productExceptSelf(arr);
    for (int val : res) 
        cout << val << " ";
    return 0;
}


